<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ClapsLearn Operations</title><style>body{font:16px system-ui;background:#f4f6fa;color:#162338;margin:0}header{background:#14253f;color:white;padding:24px}main{max-width:1280px;margin:auto;padding:24px}a{color:#17649b}header a{color:white}h1{margin:0}h2{margin-top:30px}section,details{background:white;border:1px solid #dbe2ed;border-radius:10px;padding:18px;margin:14px 0}summary{cursor:pointer;font-weight:700}form{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0}label{display:flex;flex-direction:column;font-size:13px;gap:5px}input,select,button{font:inherit;padding:9px;border:1px solid #aebed0;border-radius:5px;max-width:230px}button{background:#175e88;color:white;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:10px;border-bottom:1px solid #e6ebf2;white-space:nowrap}.scroll{overflow:auto}.notice{padding:14px;background:#fff2d1;border-radius:8px}.success{background:#d7f1e5;padding:14px}.error{background:#ffe0df;padding:14px}small{color:#506379}.tabs{display:flex;gap:18px;flex-wrap:wrap}.pagination{display:flex;gap:12px;list-style:none;padding:0}.page-link{display:block;padding:8px 12px;border:1px solid #cbd5e1;border-radius:5px}.disabled{opacity:.5}button:focus,input:focus,select:focus,summary:focus,a:focus{outline:3px solid #3a93c4;outline-offset:2px}@media(max-width:600px){main{padding:12px}header{padding:18px}form{display:block}label{margin:10px 0}input,select{max-width:100%;box-sizing:border-box;width:100%}button{margin-top:8px}}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.metrics strong{font-size:32px}.tabs [aria-current=page]{font-weight:800;text-decoration:underline}td{max-width:420px;white-space:normal;overflow-wrap:anywhere}</style></head><body><header><h1>ClapsLearn Operations</h1><p>Timetable-first, individual tuition</p><a href="{{ route('erp.index') }}">Business units</a> · <a href="{{ route('erp.tasks.mine') }}">My assigned tasks</a> · <a href="/">Existing application</a></header><main>@if(session('status'))<p class="success">{{ session('status') }}</p>@endif @if($errors->any())<div class="error"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif @yield('content')</main><script>
document.querySelectorAll('.entity-picker').forEach(function(select){
 var search=select.parentElement.querySelector('.entity-search'),timer,sequence=0;
 function load(){var ticket=++sequence,url=new URL(select.dataset.url,window.location.origin);url.searchParams.set('q',search?search.value:'');fetch(url.toString(),{headers:{Accept:'application/json'},credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error('Lookup unavailable');return r.json();}).then(function(rows){if(ticket!==sequence)return;var current=select.value;select.replaceChildren(new Option('Choose a record',''));rows.forEach(function(row){select.add(new Option(row.label,String(row.id)));});if(current)select.value=current;}).catch(function(){if(ticket===sequence){select.replaceChildren(new Option('Search unavailable; retry',''));}});}
 if(search)search.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(load,200);});load();
});
</script></body></html>